-- item-counting · Task 4 staging gate · step 3 of 3: function, plan and expectation evidence
--
-- GENERATED by tests/staging/generate-query-evidence.ts (item-counting-gate-v2.2) from
-- supabase/migrations/0035_load_production_evidence_v2.sql and MEASURE_CASES /
-- STAGING_CUTOFF. STAGING ONLY. Needs 0034, 0035 and 0036 applied on staging.
-- Read-only: everything runs in one transaction that is rolled back; no
-- ANALYZE, no ALTER of any role or setting.
--
-- Identity switches use each role's REAL session claims, which the runner
-- puts into transaction-local inka_staging.jwt_<role> settings as bound
-- parameters right after BEGIN. Run standalone, without them, the first
-- switch fails: there is no fallback to minimal claims.
--
-- 1. v2 and v1 function catalog definitions and grants; all production_events
--    policies (hashed by the gate and checked against the reviewed 0036 text).
-- 2. After every switch to the authenticated role: record claims evidence
--    (size, shape, subject, issuer — never values), apply authenticated's own
--    statement_timeout from pg_roles with SET LOCAL (as PostgREST does) and
--    record the effective settings. Over-limit statements cancel and fail.
-- 3. Owner and manager (RLS on), each of the six scopes:
--      - EXPLAIN (ANALYZE, BUFFERS) of the v2 call, three labelled runs, and of
--        the exact function body with the same arguments
--      - three runs of PostgREST's real scalar statement with the whole body
--        converted to text (byte length recorded)
--      - the function's rowCount and an independent EXISTS expectation;
--        day scopes also compare every decoded field with the table rows
-- 4. Small fixtures: staff, an empty window and invalid input.
-- Fixed cutoff for every scope: 2026-11-12T00:00:00.000Z.
--
-- Labels: EXPLAINs select 'gate:<call|body>:<role>:<scope>:<run>'; text runs
-- return 'gate:text:<role>:<scope>:<run>' in their gate column.

begin;

-- function catalog evidence: load_production_evidence_v2
select p.proname as fn_name,
       pg_get_function_identity_arguments(p.oid) as fn_args,
       pg_get_function_result(p.oid) as fn_result,
       l.lanname as fn_language,
       p.provolatile as fn_volatility,
       p.prosecdef as fn_security_definer,
       coalesce(array_to_string(p.proconfig, ','), '') as fn_config,
       md5(pg_get_functiondef(p.oid)) as fn_definition_md5
from pg_proc p join pg_namespace n on n.oid = p.pronamespace join pg_language l on l.oid = p.prolang
where n.nspname = 'public' and p.proname = 'load_production_evidence_v2';

-- function privileges: load_production_evidence_v2
select 'load_production_evidence_v2' as fn_privileges_for, r.grantee as fn_grantee,
       case when r.grantee = 'PUBLIC'
            then exists (select 1 from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                         where p.oid = 'public.load_production_evidence_v2(text, timestamptz, timestamptz, timestamptz)'::regprocedure and a.grantee = 0 and a.privilege_type = 'EXECUTE')
            else has_function_privilege(r.grantee, 'public.load_production_evidence_v2(text, timestamptz, timestamptz, timestamptz)', 'EXECUTE')
       end as can_execute
from (values ('PUBLIC'), ('anon'), ('authenticated'), ('service_role')) r(grantee);

-- function catalog evidence: load_production_evidence
select p.proname as fn_name,
       pg_get_function_identity_arguments(p.oid) as fn_args,
       pg_get_function_result(p.oid) as fn_result,
       l.lanname as fn_language,
       p.provolatile as fn_volatility,
       p.prosecdef as fn_security_definer,
       coalesce(array_to_string(p.proconfig, ','), '') as fn_config,
       md5(pg_get_functiondef(p.oid)) as fn_definition_md5
from pg_proc p join pg_namespace n on n.oid = p.pronamespace join pg_language l on l.oid = p.prolang
where n.nspname = 'public' and p.proname = 'load_production_evidence';

-- function privileges: load_production_evidence
select 'load_production_evidence' as fn_privileges_for, r.grantee as fn_grantee,
       case when r.grantee = 'PUBLIC'
            then exists (select 1 from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                         where p.oid = 'public.load_production_evidence(text, timestamptz, timestamptz, timestamptz)'::regprocedure and a.grantee = 0 and a.privilege_type = 'EXECUTE')
            else has_function_privilege(r.grantee, 'public.load_production_evidence(text, timestamptz, timestamptz, timestamptz)', 'EXECUTE')
       end as can_execute
from (values ('PUBLIC'), ('anon'), ('authenticated'), ('service_role')) r(grantee);

-- production_events policies (all of them; hashed by the gate)
select 'production_events' as policy_catalog, schemaname, tablename, policyname, permissive, roles::text[] as roles, cmd, qual, with_check
from pg_catalog.pg_policies where schemaname = 'public' and tablename = 'production_events'
order by policyname;

select pg_size_pretty(pg_total_relation_size('public.production_events')) as total_size,
       (select count(*) from public.production_events) as rows;

reset role;

select set_config('request.jwt.claims', current_setting('inka_staging.jwt_owner'), true) is not null as claims_set,
       set_config('request.jwt.claim.sub', '', true) = '' and set_config('request.jwt.claim.role', '', true) = '' as legacy_cleared;

select 'owner' as claims_for,
       octet_length(current_setting('request.jwt.claims')) as claims_bytes,
       (select string_agg(k || ':' || json_typeof(c.j -> k), ',' order by k collate "C") from json_object_keys(c.j) k) as claims_shape,
       (c.j ->> 'role') = 'authenticated' as claims_db_role_ok,
       (c.j ->> 'aud') = 'authenticated' as claims_aud_ok,
       (c.j ->> 'iss') = 'https://ybrzhrgfrnvtcwymjdrq.supabase.co/auth/v1' as claims_iss_ok,
       (c.j ->> 'exp')::bigint > extract(epoch from now()) as claims_unexpired,
       coalesce((select u.email from auth.users u where u.id::text = c.j ->> 'sub') = 'owner@inka-staging.test', false) as claims_subject_ok,
       coalesce(current_setting('request.jwt.claim.sub', true), '') = '' and coalesce(current_setting('request.jwt.claim.role', true), '') = '' as legacy_overrides_empty,
       (select p.role from public.profiles p where p.user_id::text = c.j ->> 'sub') as profile_role,
       (select string_agg(ul.location, ',' order by ul.location) from public.user_locations ul where ul.user_id::text = c.j ->> 'sub') as memberships
from (select current_setting('request.jwt.claims')::json as j) c;

set local role authenticated;

-- apply the API role's own statement_timeout (read from the catalog, never hardcoded)
do $$
declare
  entries text[];
begin
  select array_agg(c) into entries
  from pg_catalog.pg_roles r, unnest(r.rolconfig) c
  where r.rolname = 'authenticated' and c like 'statement_timeout=%';
  if entries is null or array_length(entries, 1) <> 1 then
    raise exception 'gate: authenticated must have exactly one statement_timeout setting (found %)', coalesce(array_length(entries, 1), 0);
  end if;
  execute format('set local statement_timeout = %L', substr(entries[1], length('statement_timeout=') + 1));
end
$$;

select 'owner' as timeout_for,
       current_user as current_user_name,
       session_user as session_user_name,
       (select setting::bigint from pg_catalog.pg_settings where name = 'statement_timeout') as effective_timeout_ms,
       current_setting('statement_timeout') as effective_timeout,
       (select string_agg(substr(c, length('statement_timeout=') + 1), ',')
          from pg_catalog.pg_roles r, unnest(r.rolconfig) c
         where r.rolname = 'authenticated' and c like 'statement_timeout=%') as catalog_timeout,
       (select coalesce(array_to_string(rolconfig, ', '), '') from pg_catalog.pg_roles where rolname = 'authenticated') as authenticated_config,
       (select coalesce(array_to_string(rolconfig, ', '), '') from pg_catalog.pg_roles where rolname = 'authenticator') as authenticator_config,
       (select coalesce(array_to_string(rolconfig, ', '), '') from pg_catalog.pg_roles where rolname = 'anon') as anon_config,
       current_setting('row_security') as row_security,
       current_setting('work_mem') as work_mem,
       version() as server_version;

explain (analyze, buffers) select 'gate:call:owner:au-busy-day:1' as gate,
  public.load_production_evidence_v2('au', '2026-09-14T18:00:00.000Z'::timestamptz, '2026-09-15T18:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz);

explain (analyze, buffers) select 'gate:call:owner:au-busy-day:2' as gate,
  public.load_production_evidence_v2('au', '2026-09-14T18:00:00.000Z'::timestamptz, '2026-09-15T18:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz);

explain (analyze, buffers) select 'gate:call:owner:au-busy-day:3' as gate,
  public.load_production_evidence_v2('au', '2026-09-14T18:00:00.000Z'::timestamptz, '2026-09-15T18:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz);

explain (analyze, buffers) select 'gate:body:owner:au-busy-day:1' as gate, (
SELECT CASE
    WHEN 'au'::text IS NULL OR pg_catalog.btrim('au'::text) = ''
      OR '2026-09-14T18:00:00.000Z'::timestamptz IS NULL OR '2026-09-15T18:00:00.000Z'::timestamptz IS NULL OR '2026-11-12T00:00:00.000Z'::timestamptz IS NULL
      OR NOT pg_catalog.isfinite('2026-09-14T18:00:00.000Z'::timestamptz)
      OR NOT pg_catalog.isfinite('2026-09-15T18:00:00.000Z'::timestamptz)
      OR NOT pg_catalog.isfinite('2026-11-12T00:00:00.000Z'::timestamptz)
      OR '2026-09-14T18:00:00.000Z'::timestamptz >= '2026-09-15T18:00:00.000Z'::timestamptz
    THEN NULL::json
    ELSE (
      WITH win AS (
        SELECT pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku,
               pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
        FROM public.production_events pe
        WHERE pe.location = 'au'::text
          AND pe.event_type IN ('line_verified', 'completed', 'dispatched', 'cancelled')
          AND pe.created_at >= '2026-09-14T18:00:00.000Z'::timestamptz
          AND pe.created_at < '2026-09-15T18:00:00.000Z'::timestamptz
          AND pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
      ),
      qualification AS (
        SELECT pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku,
               pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
        FROM public.production_events pe
        WHERE pe.location = 'au'::text
          AND pe.event_type = 'line_verified'
          AND pe.created_at < '2026-09-14T18:00:00.000Z'::timestamptz
          AND pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
          AND pe.order_number IN (
            SELECT w.order_number FROM win w
            WHERE w.event_type IN ('completed', 'dispatched')
              AND w.order_number IS NOT NULL
              AND pg_catalog.btrim(w.order_number) <> ''
          )
      ),
      parents AS (
        SELECT pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku,
               pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
        FROM public.production_events pe
        WHERE pe.location = 'au'::text
          AND pe.created_at < '2026-09-14T18:00:00.000Z'::timestamptz
          AND pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
          AND pe.id IN (
            SELECT w.parent_event_id FROM win w
            WHERE w.event_type = 'cancelled'
              AND w.parent_event_id IS NOT NULL
              AND w.parent_event_id <> ''
          )
      ),
      later AS (
        SELECT pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku,
               pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
        FROM public.production_events pe
        WHERE pe.location = 'au'::text
          AND pe.event_type = 'cancelled'
          AND pe.parent_event_id IS NOT NULL
          AND pe.created_at >= '2026-09-15T18:00:00.000Z'::timestamptz
          AND pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
          AND pe.parent_event_id IN (
            SELECT w.id FROM win w
            WHERE w.event_type IN ('line_verified', 'completed', 'dispatched')
          )
      ),
      evidence AS MATERIALIZED (
        SELECT * FROM win
        UNION ALL SELECT * FROM later
        UNION ALL (SELECT * FROM qualification UNION SELECT * FROM parents)
      ),
      staff_list AS MATERIALIZED (
        SELECT COALESCE(pg_catalog.array_agg(d.staff_id), '{}'::uuid[]) AS a
        FROM (SELECT DISTINCT e.staff_id FROM evidence e WHERE e.staff_id IS NOT NULL) d
      ),
      sku_list AS MATERIALIZED (
        SELECT COALESCE(pg_catalog.array_agg(d.line_sku), '{}'::text[]) AS a
        FROM (SELECT DISTINCT e.line_sku FROM evidence e WHERE e.line_sku IS NOT NULL) d
      ),
      staff_map AS (
        SELECT u.v AS staff_id, (u.n - 1)::int AS i
        FROM staff_list, pg_catalog.unnest(staff_list.a) WITH ORDINALITY AS u(v, n)
      ),
      sku_map AS (
        SELECT u.v AS line_sku, (u.n - 1)::int AS i
        FROM sku_list, pg_catalog.unnest(sku_list.a) WITH ORDINALITY AS u(v, n)
      ),
      agg AS (
        SELECT pg_catalog.count(*) AS n,
               pg_catalog.json_agg(
                 pg_catalog.json_build_array(
                   e.id, sm.i, e.department, e.order_number, km.i, e.line_quantity,
                   e.event_type, e.created_at, e.parent_event_id, e.cs_case_id)) AS rows
        FROM evidence e
        LEFT JOIN staff_map sm ON sm.staff_id = e.staff_id
        LEFT JOIN sku_map km ON km.line_sku = e.line_sku
      )
      SELECT pg_catalog.json_build_object(
        'version', 2,
        'site', 'au'::text,
        'startUtc', '2026-09-14T18:00:00.000Z'::timestamptz,
        'endUtcExclusive', '2026-09-15T18:00:00.000Z'::timestamptz,
        'asOfUtc', '2026-11-12T00:00:00.000Z'::timestamptz,
        'complete', true,
        'rowCount', agg.n,
        'staffIds', (SELECT pg_catalog.to_json(staff_list.a) FROM staff_list),
        'skus', (SELECT pg_catalog.to_json(sku_list.a) FROM sku_list),
        'rows', COALESCE(agg.rows, '[]'::json)
      )
      FROM agg
    )
  END
) as evidence;

-- real PostgREST scalar shape, full body converted to text
WITH pgrst_source AS (
  SELECT pgrst_call.pgrst_scalar
  FROM (SELECT '{"p_site":"au","p_start_utc":"2026-09-14T18:00:00.000Z","p_end_utc_exclusive":"2026-09-15T18:00:00.000Z","p_as_of_utc":"2026-11-12T00:00:00.000Z"}'::json AS json_data) pgrst_payload,
  LATERAL (SELECT "p_site", "p_start_utc", "p_end_utc_exclusive", "p_as_of_utc"
           FROM json_to_record(pgrst_payload.json_data) AS _("p_site" text, "p_start_utc" timestamp with time zone,
                "p_end_utc_exclusive" timestamp with time zone, "p_as_of_utc" timestamp with time zone) LIMIT 1) pgrst_body,
  LATERAL (SELECT "public"."load_production_evidence_v2"("p_site" := pgrst_body."p_site", "p_start_utc" := pgrst_body."p_start_utc",
           "p_end_utc_exclusive" := pgrst_body."p_end_utc_exclusive", "p_as_of_utc" := pgrst_body."p_as_of_utc") pgrst_scalar) pgrst_call
)
SELECT 'gate:text:owner:au-busy-day:1' AS gate,
       octet_length((coalesce(json_agg(_postgrest_t.pgrst_scalar) -> 0, 'null'::json))::text) AS body_bytes,
       current_setting('statement_timeout') AS effective_timeout
FROM (SELECT "load_production_evidence_v2".* FROM "pgrst_source" AS "load_production_evidence_v2" LIMIT ALL OFFSET 0) _postgrest_t;

-- real PostgREST scalar shape, full body converted to text
WITH pgrst_source AS (
  SELECT pgrst_call.pgrst_scalar
  FROM (SELECT '{"p_site":"au","p_start_utc":"2026-09-14T18:00:00.000Z","p_end_utc_exclusive":"2026-09-15T18:00:00.000Z","p_as_of_utc":"2026-11-12T00:00:00.000Z"}'::json AS json_data) pgrst_payload,
  LATERAL (SELECT "p_site", "p_start_utc", "p_end_utc_exclusive", "p_as_of_utc"
           FROM json_to_record(pgrst_payload.json_data) AS _("p_site" text, "p_start_utc" timestamp with time zone,
                "p_end_utc_exclusive" timestamp with time zone, "p_as_of_utc" timestamp with time zone) LIMIT 1) pgrst_body,
  LATERAL (SELECT "public"."load_production_evidence_v2"("p_site" := pgrst_body."p_site", "p_start_utc" := pgrst_body."p_start_utc",
           "p_end_utc_exclusive" := pgrst_body."p_end_utc_exclusive", "p_as_of_utc" := pgrst_body."p_as_of_utc") pgrst_scalar) pgrst_call
)
SELECT 'gate:text:owner:au-busy-day:2' AS gate,
       octet_length((coalesce(json_agg(_postgrest_t.pgrst_scalar) -> 0, 'null'::json))::text) AS body_bytes,
       current_setting('statement_timeout') AS effective_timeout
FROM (SELECT "load_production_evidence_v2".* FROM "pgrst_source" AS "load_production_evidence_v2" LIMIT ALL OFFSET 0) _postgrest_t;

-- real PostgREST scalar shape, full body converted to text
WITH pgrst_source AS (
  SELECT pgrst_call.pgrst_scalar
  FROM (SELECT '{"p_site":"au","p_start_utc":"2026-09-14T18:00:00.000Z","p_end_utc_exclusive":"2026-09-15T18:00:00.000Z","p_as_of_utc":"2026-11-12T00:00:00.000Z"}'::json AS json_data) pgrst_payload,
  LATERAL (SELECT "p_site", "p_start_utc", "p_end_utc_exclusive", "p_as_of_utc"
           FROM json_to_record(pgrst_payload.json_data) AS _("p_site" text, "p_start_utc" timestamp with time zone,
                "p_end_utc_exclusive" timestamp with time zone, "p_as_of_utc" timestamp with time zone) LIMIT 1) pgrst_body,
  LATERAL (SELECT "public"."load_production_evidence_v2"("p_site" := pgrst_body."p_site", "p_start_utc" := pgrst_body."p_start_utc",
           "p_end_utc_exclusive" := pgrst_body."p_end_utc_exclusive", "p_as_of_utc" := pgrst_body."p_as_of_utc") pgrst_scalar) pgrst_call
)
SELECT 'gate:text:owner:au-busy-day:3' AS gate,
       octet_length((coalesce(json_agg(_postgrest_t.pgrst_scalar) -> 0, 'null'::json))::text) AS body_bytes,
       current_setting('statement_timeout') AS effective_timeout
FROM (SELECT "load_production_evidence_v2".* FROM "pgrst_source" AS "load_production_evidence_v2" LIMIT ALL OFFSET 0) _postgrest_t;

select 'owner' as role, 'au-busy-day' as scope,
  substring((public.load_production_evidence_v2('au', '2026-09-14T18:00:00.000Z'::timestamptz, '2026-09-15T18:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz))::text from '"rowCount" *: *([0-9]+)')::bigint as fn_row_count;

-- independent expectation (EXISTS form)
with w as (
  select pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku, pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
  from public.production_events pe
  where pe.location = 'au' and pe.created_at >= '2026-09-14T18:00:00.000Z'::timestamptz and pe.created_at < '2026-09-15T18:00:00.000Z'::timestamptz and pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz and pe.event_type in ('line_verified', 'completed', 'dispatched', 'cancelled')
), q as (
  select x.id, x.staff_id, x.department, x.order_number, x.line_sku, x.line_quantity, x.event_type, x.created_at, x.parent_event_id, x.cs_case_id from public.production_events x
  where x.location = 'au' and x.event_type = 'line_verified' and x.created_at < '2026-09-14T18:00:00.000Z'::timestamptz and x.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
    and exists (select 1 from w where w.event_type in ('completed', 'dispatched')
                and coalesce(btrim(w.order_number), '') <> '' and w.order_number = x.order_number)
), p as (
  select x.id, x.staff_id, x.department, x.order_number, x.line_sku, x.line_quantity, x.event_type, x.created_at, x.parent_event_id, x.cs_case_id from public.production_events x
  where x.location = 'au' and x.created_at < '2026-09-14T18:00:00.000Z'::timestamptz and x.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
    and exists (select 1 from w where w.event_type = 'cancelled' and coalesce(w.parent_event_id, '') <> '' and w.parent_event_id = x.id)
), l as (
  select x.id, x.staff_id, x.department, x.order_number, x.line_sku, x.line_quantity, x.event_type, x.created_at, x.parent_event_id, x.cs_case_id from public.production_events x
  where x.location = 'au' and x.event_type = 'cancelled' and x.created_at >= '2026-09-15T18:00:00.000Z'::timestamptz and x.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz
    and exists (select 1 from w where w.event_type in ('line_verified', 'completed', 'dispatched') and w.id = x.parent_event_id)
), expected as (
  select * from w union select * from q union select * from p union select * from l
)
select 'owner' as role, 'au-busy-day' as scope,
  (select count(*) from w) as window_rows,
  (select count(*) from q) as qualification_rows,
  (select count(*) from p) as parent_rows,
  (select count(*) from l) as later_rows,
  (select count(*) from expected) as independent_total;

-- field-by-field: decoded v2 rows versus the independent table rows
with w as (
  select pe.id, pe.staff_id, pe.department, pe.order_number, pe.line_sku, pe.line_quantity, pe.event_type, pe.created_at, pe.parent_event_id, pe.cs_case_id
  from public.production_events pe
  where pe.location = 'au' and pe.created_at >= '2026-09-14T18:00:00.000Z'::timestamptz and pe.created_at < '2026-09-15T18:00:00.000Z'::timestamptz and pe.created_at <= '2026-11-12T00:00:00.000Z'::timestamptz and pe.event_type in ('line_verified', 'completed', 'dispatched', 'cancelled')
), q as (
  select x.id, x.staff_id, x.department, x.order_number, x.line_sku, x.line_quantity, x.event_type, x.created_at, x.parent_event_id, x.cs_case_id from public.production_events x
