v2 as (select public.load_production_evidence_v2('us', '2026-03-08T09:00:00.000Z'::timestamptz, '2026-03-09T09:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz) as b),
