v2 as (select public.load_production_evidence_v2('uk', '2026-03-29T03:00:00.000Z'::timestamptz, '2026-03-30T03:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz) as b),
