select (public.load_production_evidence_v2('au', '2020-01-01T13:00:00.000Z'::timestamptz, '2020-01-02T13:00:00.000Z'::timestamptz, '2026-11-12T00:00:00.000Z'::timestamptz) ->> 'rowCount')::bigint as empty_window_row_count,
